  4→-->
  5→<script lang="ts">
  6→	import type { TaskDetail } from '@kynetic-ai/shared';
  7→	import { base } from '$app/paths';
  8→	import {
  9→		fetchTask,
 10→		startTask,
 11→		submitTask,
 12→		completeTask,
 13→		blockTask,
 14→		addTaskNote
 15→	} from '$lib/api';
