   159→
   160→    // Helper to create a valid second project for multi-project tests
   161→    // AC: @multi-directory-daemon ac-25 - Tests need multiple valid projects
   162→    async function createSecondProject(): Promise<string> {
   163→      const secondProjectPath = tempDir + '-second';
   164→      const secondKspecDir = join(secondProjectPath, '.kspec');
   165→
   166→      // Create project directory with valid .kspec structure
   167→      mkdirSync(secondKspecDir, { recursive: true });
   168→
   169→      // Create minimal kynetic.yaml
   170→      writeFileSync(
   171→        join(secondKspecDir, 'kynetic.yaml'),
   172→        `kynetic: "1.0"
   173→project: Second Test Project
   174→`
   175→      );
   176→
   177→      // Create project.tasks.yaml (empty tasks file)
   178→      writeFileSync(
   179→        join(secondKspecDir, 'project.tasks.yaml'),
   180→        `# Tasks for second test project
   181→tasks: []
   182→`
   183→      );
   184→
   185→      // Initialize git repo in second project
   186→      execSync('git init', { cwd: secondProjectPath, stdio: 'ignore' });
   187→      execSync('git config user.email "test@test.com"', { cwd: secondProjectPath, stdio: 'ignore' });
   188→      execSync('git config user.name "Test"', { cwd: secondProjectPath, stdio: 'ignore' });
   189→
   190→      // Set up shadow worktree simulation (same as main project)
   191→      const gitWorktreesDir = join(secondProjectPath, '.git', 'worktrees', '-kspec');
   192→      mkdirSync(gitWorktreesDir, { recursive: true });
   193→      writeFileSync(join(secondKspecDir, '.git'), `gitdir: ${gitWorktreesDir}\n`);
   194→      writeFileSync(join(gitWorktreesDir, 'gitdir'), `${join(secondProjectPath, '.git')}\n`);
   195→      writeFileSync(join(gitWorktreesDir, 'HEAD'), 'ref: refs/heads/kspec-meta\n');
   196→
   197→      // Register second project with daemon
   198→      const response = await fetch(`http://localhost:${DAEMON_PORT}/api/projects`, {
   199→        method: 'POST',
   200→        headers: { 'Content-Type': 'application/json' },
   201→        body: JSON.stringify({ path: secondProjectPath }),
   202→      });
   203→
   204→      if (!response.ok) {
   205→        const error = await response.text();
   206→        throw new Error(`Failed to register second project: ${error}`);
   207→      }
   208→
   209→      return secondProjectPath;
   210→    }
   211→
   212→    // Provide fixture to test
   213→    await use({ tempDir, kspecDir, createSecondProject });
   214→
   215→    // Cleanup: stop daemon - pass project root to match start
   216→    spawnSync('kspec', ['serve', 'stop', '--kspec-dir', tempDir], {
   217→      cwd: tempDir,
   218→      encoding: 'utf-8',
   219→    });
   220→    await new Promise((r) => setTimeout(r, 1000));
   221→
   222→    // Remove temp directories (main and any second project)
   223→    try {
   224→      rmSync(tempDir, { recursive: true, force: true });
   225→      // Also clean up second project if it exists
   226→      rmSync(tempDir + '-second', { recursive: true, force: true });
   227→    } catch {
   228→      // Best effort cleanup
   229→    }
   230→  },
   231→});
   232→
   233→export { expect };
